from lib import *
L = lambda *a, **k: lesson(23, "A0", *a, **k)
V = "verb"
A = "adjective"
L(1, "Ліворуч, праворуч, прямо", "Зрозуміти й дати найпростішу вказівку дороги.",
 "Три вказівки, яких досить майже завжди: Turn left — «поверніть ліворуч», Turn right — «поверніть праворуч», Go straight on — «ідіть прямо». Right ви знаєте як «правильний»; тут воно означає «праворуч». I'm lost — «я заблукав».",
 [W("turn", "/tɜːn/", V, "повертати", "Turn left.", "Поверніть ліворуч."),
  W("left", "/left/", "adverb", "ліворуч", "Turn left at the bank.", "Біля банку поверніть ліворуч."),
  W("right", "/raɪt/", "adverb", "праворуч", "Turn right.", "Поверніть праворуч."),
  W("straight on", "/ˌstreɪt ˈɒn/", "adverb", "прямо", "Go straight on.", "Ідіть прямо."),
  W("lost", "/lɒst/", A, "той, що заблукав", "I'm lost.", "Я заблукав.")],
 [li("How far is the station?", "Повторимо. До вокзалу приблизно два кілометри. Що відповісти?", ["It's about two kilometres.", "It's about two kilometres long time.", "It's far two."], "It's about two kilometres."),
  mt([("turn", "повертати"), ("left", "ліворуч"), ("right", "праворуч"), ("straight on", "прямо"), ("lost", "той, що заблукав")], "У right і straight літери gh не вимовляються."),
  liu("Turn left.", "Прослухайте. Куди повернути?", ["Ліворуч", "Праворуч", "Іти прямо"], "Left — ліворуч."),
  liu("Go straight on.", "Прослухайте. Що треба зробити?", ["Іти прямо", "Повернути праворуч", "Повернутися назад"], "Straight on — прямо."),
  liu("Turn right at the traffic lights.", "Прослухайте. Де й куди повернути?", ["Біля світлофора праворуч", "Біля світлофора ліворуч", "Біля банку праворуч"], "Right at the traffic lights."),
  mc("Як сказати «Я заблукав»?", ["I'm lost.", "I have lost.", "I lost am."], "I'm lost."),
  fb("___ left at the corner.", ["Turn", "Go to", "Straight"], "Turn left."),
  fb("Go ___ on. Don't turn.", ["straight", "left", "lost"], "Go straight on."),
  mcu("Що тут означає right: Turn right?", ["Праворуч", "Правильно", "Прямо"], "У вказівках дороги right — праворуч."),
  bs("Поверніть ліворуч біля банку.", ["Turn", "left", "at", "the", "bank"], ["right", "on"], "Turn left at the bank."),
  tr("Ідіть прямо.", ["Go straight on", "Go straight"], "Go straight on."),
  li("Excuse me, I'm lost. Where is the station?", "Вокзал прямо, потім праворуч. Що відповісти?", ["Go straight on, then turn right.", "Go right on, then turn straight.", "Turn straight, then go right on."], "Go straight on, then turn right.")])
L(2, "Перший поворот ліворуч", "Зрозуміти вказівки з кількома кроками.",
 "Take the first left — «перший поворот ліворуч». Take the second right — «другий праворуч». Порядкові слова: first, second, third. Cross the road — перейти дорогу. Go along the street — іти вздовж вулиці. Go past the bank — пройти повз банк.",
 [W("second", "/ˈsekənd/", A, "другий", "The second street.", "Друга вулиця."),
  W("third", "/θɜːd/", A, "третій", "The third door.", "Треті двері."),
  W("cross", "/krɒs/", V, "переходити", "Cross the road.", "Перейдіть дорогу."),
  W("along", "/əˈlɒŋ/", "preposition", "уздовж", "Go along this street.", "Ідіть цією вулицею."),
  W("go past", "/ˌɡəʊ ˈpɑːst/", V, "проходити повз", "Go past the church.", "Пройдіть повз церкву.")],
 [fb("Go ___ on, then turn left.", ["straight", "right", "lost"], "Go straight on.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("first", "перший"), ("second", "другий"), ("third", "третій")], "Перший, другий, третій."),
  mt([("cross", "переходити"), ("along", "уздовж"), ("go past", "проходити повз"), ("turn", "повертати")], "Дії в дорозі."),
  liu("Take the second left.", "Прослухайте. Який поворот потрібен?", ["Другий ліворуч", "Перший ліворуч", "Другий праворуч"], "The second left."),
  liu("Cross the road and go past the supermarket.", "Прослухайте. Що треба зробити?", ["Перейти дорогу й пройти повз супермаркет", "Повернути біля супермаркету", "Зайти в супермаркет"], "Cross the road, go past the supermarket."),
  fb("Take the ___ right. It's street number one.", ["first", "third", "along"], "Number one — first."),
  fb("___ the road at the traffic lights.", ["Cross", "Along", "Past"], "Cross the road."),
  fb("Go ___ this street to the end.", ["along", "cross", "third"], "Go along this street."),
  mc("Як сказати «третя вулиця праворуч»?", ["the third street on the right", "the three street on right", "third the street right"], "The third street on the right."),
  bs("Перший поворот ліворуч.", ["Take", "the", "first", "left"], ["second", "turn"], "Take the first left."),
  tr("Перейдіть дорогу.", ["Cross the road"], "Cross the road."),
  li("Excuse me, where is the post office?", "Треба пройти повз банк і повернути у другу вулицю праворуч. Що відповісти?", ["Go past the bank and take the second right.", "Go past the bank and take the two right.", "Go the bank past and second right take."], "Go past the bank and take the second right.")])
L(3, "Як дістатися до вокзалу?", "Спитати дорогу й зрозуміти, з якого боку потрібне місце.",
 "How do I get to…? — «Як мені дістатися до…?». On the left — «ліворуч, з лівого боку». On the right — «праворуч». Which way? — «У який бік?». This way — «сюди».",
 [W("get to", "/ˈɡet tuː/", V, "дістатися до", "How do I get to the station?", "Як мені дістатися до вокзалу?"),
  W("way", "/weɪ/", "noun", "шлях, напрямок", "Which way?", "У який бік?"),
  W("on the left", "/ɒn ðə ˈleft/", "phrase", "ліворуч, з лівого боку", "It's on the left.", "Це ліворуч."),
  W("on the right", "/ɒn ðə ˈraɪt/", "phrase", "праворуч, з правого боку", "The bank is on the right.", "Банк праворуч."),
  W("sign", "/saɪn/", "noun", "знак, вказівник", "Follow the signs.", "Ідіть за вказівниками.")],
 [fb("___ the road and turn left.", ["Cross", "Along", "Second"], "Cross the road.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("get to", "дістатися до"), ("way", "шлях"), ("sign", "вказівник"), ("on the left", "ліворуч"), ("on the right", "праворуч")], "У sign літера g не вимовляється."),
  liu("How do I get to the museum?", "Прослухайте. Що питає людина?", ["Як дістатися до музею", "Де музей", "Чи далеко музей"], "How do I get to…?"),
  liu("The pharmacy is on the left, next to the bank.", "Прослухайте. Де аптека?", ["Ліворуч, біля банку", "Праворуч, біля банку", "Навпроти банку"], "On the left."),
  mc("Як спитати дорогу до готелю?", ["How do I get to the hotel?", "How I get the hotel?", "How do I get the hotel to?"], "How do I get to the hotel?"),
  fb("The café is ___ the right.", ["on", "in", "at"], "On the right."),
  fb("How do I ___ to the airport?", ["get", "turn", "way"], "Get to."),
  fb("Which ___ is the city centre?", ["way", "sign", "left"], "Which way…?"),
  mcu("Що означає This way, please?", ["Сюди, будь ласка", "Це шлях, будь ласка", "Іншим шляхом"], "This way — сюди."),
  bs("Як мені дістатися до вокзалу?", ["How", "do", "I", "get", "to", "the", "station"], ["way"], "How do I get to the station?"),
  tr("Це ліворуч.", ["It's on the left", "It is on the left"], "It's on the left."),
  li("Excuse me, how do I get to the park?", "Парк прямо, він буде праворуч. Що відповісти?", ["Go straight on. It's on the right.", "Go straight on. It's in the right.", "Straight go. Right is it."], "Go straight on. It's on the right.")])
L(4, "Це п'ять хвилин пішки", "Зрозуміти, як далеко йти, і вказівку з орієнтирами.",
 "Відстань: about two hundred metres — приблизно двісті метрів. Час: It's a five-minute walk — «це п'ять хвилин пішки». Until — «аж до»: Go straight on until the bridge. After that — «після цього». You can't miss it — «ви не проминете».",
 [W("metre", "/ˈmiːtə/", "noun", "метр", "About a hundred metres.", "Приблизно сто метрів."),
  W("a five-minute walk", "/ə ˌfaɪv mɪnɪt ˈwɔːk/", "phrase", "п'ять хвилин пішки", "It's a five-minute walk.", "Це п'ять хвилин пішки."),
  W("after that", "/ˌɑːftə ˈðæt/", "phrase", "після цього", "After that, turn left.", "Після цього поверніть ліворуч."),
  W("you can't miss it", "/juː ˌkɑːnt ˈmɪs ɪt/", "phrase", "ви не проминете", "It's a big building. You can't miss it.", "Це велика будівля. Ви не проминете."),
  W("building", "/ˈbɪldɪŋ/", "noun", "будівля", "A big white building.", "Велика біла будівля.")],
 [fb("The bank is ___ the left.", ["on", "at", "in"], "On the left.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("metre", "метр"), ("building", "будівля"), ("after that", "після цього"), ("you can't miss it", "ви не проминете")], "Слова для точнішої вказівки."),
  liu("It's about three hundred metres.", "Прослухайте. Як далеко?", ["Приблизно 300 метрів", "Приблизно 3 кілометри", "Рівно 30 метрів"], "Three hundred metres."),
  liu("It's a ten-minute walk.", "Прослухайте. Скільки йти?", ["10 хвилин пішки", "10 хвилин машиною", "10 кілометрів"], "A ten-minute walk."),
  liu("Go straight on until the bridge. After that, turn right.", "Прослухайте. Де повернути праворуч?", ["Після мосту", "Перед мостом", "Одразу"], "Until the bridge, after that turn right."),
  fb("Go straight on ___ the traffic lights.", ["until", "after that", "metre"], "Until — аж до."),
  fb("It's a big red ___. You can't miss it.", ["building", "metre", "walk"], "A big red building."),
  mc("Як сказати «Це п'ять хвилин пішки»?", ["It's a five-minute walk.", "It's a five-minutes walk.", "It's five minute walking."], "A five-minute walk — minute без -s."),
  mcu("Що означає You can't miss it?", ["Ви обов'язково це побачите", "Ви не можете туди йти", "Ви це пропустили"], "You can't miss it — ви не проминете."),
  bs("Після цього поверніть ліворуч.", ["After", "that", "turn", "left"], ["until", "right"], "After that, turn left."),
  tr("Це приблизно сто метрів.", ["It's about a hundred metres", "It's about one hundred metres", "It is about a hundred metres"], "It's about a hundred metres."),
  li("Is the museum far?", "Музей близько, п'ять хвилин пішки. Що відповісти?", ["No, it's a five-minute walk.", "No, it's far five minutes.", "Yes, it's a five-minute walk near."], "No, it's a five-minute walk.")])
L(5, "Дуже дякую!", "Перепитати, якщо не зрозуміли, і подякувати за допомогу.",
 "Якщо не зрозуміли: Could you show me on the map? Перевірити напрямок: Is this the right way to the station? Якщо пішли не туди, вам скажуть Go back — «поверніться». Подяка: Thank you very much. Відповідь: You're welcome — «будь ласка, прошу».",
 [W("you're welcome", "/jɔː ˈwelkəm/", "phrase", "будь ласка (у відповідь на подяку)", "Thank you. — You're welcome.", "Дякую. — Будь ласка."),
  W("very much", "/ˌveri ˈmʌtʃ/", "phrase", "дуже", "Thank you very much.", "Дуже дякую."),
  W("go back", "/ˌɡəʊ ˈbæk/", V, "повертатися назад", "Go back to the corner.", "Поверніться до рогу."),
  W("the right way", "/ðə ˌraɪt ˈweɪ/", "phrase", "правильний шлях", "Is this the right way?", "Я правильно йду?"),
  W("the wrong way", "/ðə ˌrɒŋ ˈweɪ/", "phrase", "неправильний шлях", "This is the wrong way.", "Це не той шлях.")],
 [fb("It's a big building. You can't ___ it.", ["miss", "walk", "turn"], "You can't miss it.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("you're welcome", "будь ласка (на подяку)"), ("very much", "дуже"), ("go back", "повертатися назад"), ("the right way", "правильний шлях"), ("the wrong way", "неправильний шлях")], "Please кажуть, коли просять. You're welcome — коли вам подякували."),
  liu("Is this the right way to the station?", "Прослухайте. Що питає людина?", ["Чи правильно вона йде до вокзалу", "Де вокзал", "Чи далеко вокзал"], "The right way — правильний шлях."),
  liu("No, this is the wrong way. Go back to the traffic lights.", "Прослухайте. Що треба зробити?", ["Повернутися до світлофора", "Іти прямо до світлофора", "Повернути біля світлофора"], "Go back — поверніться."),
  mc("Вам кажуть Thank you very much. Що відповісти?", ["You're welcome.", "Please.", "Yes, thank you."], "You're welcome."),
  mc("Ви не зрозуміли пояснення. Що попросити?", ["Could you show me on the map?", "Could you map me?", "Show the map you?"], "Could you show me on the map?"),
  fb("Thank you very ___!", ["much", "many", "well"], "Thank you very much."),
  fb("This is the wrong way. Go ___.", ["back", "past", "along"], "Go back."),
  fb("Is this the right ___ to the centre?", ["way", "sign", "walk"], "The right way."),
  bs("Я правильно йду до вокзалу?", ["Is", "this", "the", "right", "way", "to", "the", "station"], ["wrong"], "Is this the right way to the station?"),
  tr("Дуже дякую.", ["Thank you very much", "Thanks very much"], "Thank you very much."),
  li("It's the second street on the left.", "Вам пояснили дорогу. Що сказати?", ["Thank you very much!", "You're welcome!", "Go back!"], "Thank you very much!")])
