  tr("Я заблукав.", ["I'm lost", "I am lost"], "I'm lost."),
  liu("Take the third right, then go straight on until the river.", "Прослухайте. Який поворот потрібен?", ["Третій праворуч", "Другий праворуч", "Третій ліворуч"], "The third right."),
  fb("The hotel is ___ the right, opposite the park.", ["on", "at", "in"], "On the right."),
